import java.util.Scanner;

public class Main {
    static int MAX_K = 40;
    static int MAX_COUNT = 100;

    static class Matrix {
        long[][] mat;

        Matrix(int rows, int cols) {
            mat = new long[rows][cols];
        }

        static Matrix multiply(Matrix A, Matrix B) {
            int aRows = A.mat.length;
            int aCols = A.mat[0].length;
            int bRows = B.mat.length;
            int bCols = B.mat[0].length;
            Matrix C = new Matrix(aRows, bCols);
            for (int i = 0; i < aRows; i++) {
                for (int j = 0; j < bCols; j++) {
                    long sum = 0;
                    for (int k = 0; k < aCols; k++) {
                        sum += A.mat[i][k] * B.mat[k][j];
                    }
                    C.mat[i][j] = sum;
                }
            }
            return C;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        int K = sc.nextInt();

        int count = 0;
        long base = 1;
        while (base <= N) {
            base *= K;
            count++;
        }
        base /= K;

        int[] digits = new int[count];
        long tempN = N;
        long tempBase = base;
        for (int i = 0; i < count; i++) {
            digits[i] = (int) (tempN / tempBase);
            tempN %= tempBase;
            tempBase /= K;
        }

        Matrix[] R = new Matrix[MAX_K + 1];
        for (int i = 0; i <= K; i++) {
            R[i] = new Matrix(K + 1, K + 1);
        }

        Matrix[][] D = new Matrix[MAX_COUNT + 1][MAX_K];
        for (int i = 0; i <= count; i++) {
            for (int j = 0; j < K; j++) {
                D[i][j] = new Matrix(K + 1, K + 1);
            }
        }

        // Initialize R[0] and R[1]
        R[0].mat[K][K] = 1;
        R[1].mat[K][K] = 1;
        for (int j = 0; j < K; j++) {
            R[0].mat[j][j] = 1;
            R[1].mat[(j + K - 1) % K][j] = 1;
        }
        for (int j = 2; j <= K; j++) {
            R[j] = Matrix.multiply(R[j - 1], R[1]);
        }

        // Initialize D[0][0]
        for (int j = 0; j < K; j++) {
            D[0][0].mat[j][j] = 1;
            D[0][0].mat[j][0] = 1;
        }

        int total = count;
        for (int i = 0; i <= total; i++) {
            for (int j = 1; j < K; j++) {
                D[i][j] = Matrix.multiply(Matrix.multiply(R[K - j], D[i][0]), R[j]);
            }
            if (i + 1 <= total) {
                D[i + 1][0] = D[i][K - 1];
            }
        }

        Matrix answer = new Matrix(1, K + 1);
        answer.mat[0][K] = 1;

        int mod_sum = 0;
        for (int i = 0; i < total; i++) {
            if (digits[i] != 0) {
                Matrix temp1 = Matrix.multiply(Matrix.multiply(R[K - mod_sum], D[total - i - 1][digits[i] - 1]), R[mod_sum]);
                answer = Matrix.multiply(answer, temp1);
            }
            mod_sum += digits[i];
            mod_sum %= K;
        }

        long result = 0;
        for (int i = 0; i <= K; i++) {
            result += answer.mat[0][i];
        }
        System.out.println(result);
        sc.close();
    }
}

